17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Optional;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
37	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateEmailException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
42	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
113	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
120	        prepareNewOwner(ownerFieldsDto, registrationDate);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setRegistrationDate(registrationDate);
124	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
125	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
126	        assignHousehold(owner, ownerFieldsDto);
127	        this.clinicService.saveOwner(owner);
128	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
129	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
130	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
131	            ownerMapper.membershipLevel(owner));
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
142	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
143	        if (currentOwner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
151	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Transactional
158	    @Override
159	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        this.clinicService.deleteOwner(owner);
165	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        HttpHeaders headers = new HttpHeaders();
176	        Pet pet = petMapper.toPet(petFieldsDto);
177	        owner.setId(ownerId);
178	        pet.setOwner(owner);
179	        pet.getType().setName(null);
180	        this.clinicService.savePet(pet);
181	        PetDto petDto = petMapper.toPetDto(pet);
182	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
183	            .buildAndExpand(pet.getId()).toUri());
184	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner != null) {
192	            Pet currentPet = this.clinicService.findPetById(petId);
193	            if (currentPet != null) {
194	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
