289	    /**
290	     * The maximum number of owners that may be created on a single day. Once this many owners
291	     * already carry today's {@code registrationDate}, no further owner may be created today.
292	     */
293	    private static final long DAILY_OWNER_LIMIT = 100L;
294	
295	    /**
296	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
297	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
298	     * date the new owner would be stored with, so owners are capped per business day. When the limit
299	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
300	     * advice renders as a 429 Too Many Requests response.
301	     *
302	     * @param registrationDate the adjusted business-day registration date of the owner being created
303	     */
304	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
305	        long count = this.clinicService.findAllOwners().stream()
306	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
307	            .count();
308	        if (count >= DAILY_OWNER_LIMIT) {
309	            throw new DailyOwnerLimitExceededException(registrationDate);
310	        }
311	    }
