362	    /**
363	     * Builds the customer code assigned to a newly created owner. The code is formatted as
364	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
365	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
366	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
367	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
368	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
369	     *
370	     * @param city the owner's city
371	     * @param lastName the owner's last name
372	     * @return the formatted customer code
373	     */
374	    private String nextCustomerCode(String city, String lastName) {
375	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
376	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
377	        long sequence = this.clinicService.findAllOwners().stream()
378	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
379	            .count() + 1L;
380	        return String.format("%s-%s-%04d", city3, last3, sequence);
381	    }
