603	    /**
604	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
605	     * set to {@code true}. The identifier is the one the owner would receive
606	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
607	     * household identity so every owner in the same household resolves to the same stable value.
608	     * The new owner receives that value, and any existing household mates that do not yet carry it
609	     * are updated so the whole household shares one identifier. When the request did not opt in the
610	     * owner is left without a household identifier.
611	     *
612	     * @param owner the newly created owner, mutated in place with its household identifier
613	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
614	     */
615	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
616	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
617	        if (householdId == null) {
618	            return;
619	        }
620	        owner.setHouseholdId(householdId);
621	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
622	            if (!householdId.equals(mate.getHouseholdId())) {
623	                mate.setHouseholdId(householdId);
624	                this.clinicService.saveOwner(mate);
625	            }
626	        }
627	    }
628	
629	    /**
630	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
631	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
632	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
633	     * from the owner's household identity (its {@code lastName} and {@code address}, see
634	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
635	     * later store and every household mate resolves to the same identifier. When the request did not
636	     * opt in the owner belongs to no shared household and {@code null} is returned.
637	     *
638	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
639	     * @return the household identifier the owner would receive, or {@code null} when it shares none
640	     */
641	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
642	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
643	            return null;
644	        }
645	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
646	    }
647	
648	    /**
649	     * Derives the stable {@code householdId} shared by every owner in the household identified by
650	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
651	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
652	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
653	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
654	     *
655	     * @param lastName the household's last name
656	     * @param address the household's address
657	     * @return the deterministic household identifier
658	     */
659	    private String householdIdFor(String lastName, String address) {
660	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
661	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
662	        try {
663	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
664	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
665	            StringBuilder sb = new StringBuilder();
666	            for (int i = 0; i < 8; i++) {
667	                sb.append(String.format("%02X", digest[i]));
668	            }
669	            return "HH-" + sb;
670	        }
671	        catch (java.security.NoSuchAlgorithmException e) {
672	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
673	        }
674	    }
