676	    /**
677	     * Counts the owners that belong to the household identified by the given {@code householdId},
678	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
679	     * of owners, so after a create it reflects the household's size including the newly persisted
680	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
681	     * household and yields {@code 0}.
682	     *
683	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
684	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
685	     */
686	    private int countHouseholdMembers(String householdId) {
687	        if (householdId == null) {
688	            return 0;
689	        }
690	        return (int) this.clinicService.findAllOwners().stream()
691	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
692	            .count();
693	    }
