695	    /**
696	     * Finds an existing owner that shares a household with the given {@code lastName} and
697	     * {@code address}. When several owners match, the first one encountered is returned.
698	     *
699	     * @param lastName the last name to match on
700	     * @param address the address to match on
701	     * @return the first owner sharing the household, or empty when none exists
702	     */
703	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
704	        return findHouseholdMates(lastName, address).stream().findFirst();
705	    }
706	
707	    /**
708	     * Finds every existing owner that shares a household with the given {@code lastName} and
709	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
710	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
711	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
712	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
713	     * every rule that reasons about households.
714	     *
715	     * @param lastName the last name to match on
716	     * @param address the address to match on
717	     * @return the owners sharing the household, in encounter order (possibly empty)
718	     */
719	    private List<Owner> findHouseholdMates(String lastName, String address) {
720	        String normalizedLastName = collapseWhitespace(lastName);
721	        String normalizedAddress = normalizeAddress(address);
722	        return this.clinicService.findAllOwners().stream()
723	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
724	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
725	            .toList();
726	    }
727	
728	    /**
729	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
730	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
731	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
732	     *
733	     * @param value the value to collapse, or {@code null}
734	     * @return the whitespace-collapsed value, never {@code null}
735	     */
736	    private String collapseWhitespace(String value) {
737	        if (value == null) {
738	            return "";
739	        }
740	        return value.trim().replaceAll("\\s+", " ");
741	    }
742	
743	    /**
744	     * Common street-type abbreviations expanded during address normalization, keyed by their
745	     * upper-cased token.
746	     */
747	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
748	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
749	
750	    /**
751	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
752	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
753	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
754	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
755	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
756	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
757	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
758	     * everywhere an address is stored or compared.
759	     *
760	     * @param address the submitted address value, or {@code null}
761	     * @return the normalized address, never {@code null}
762	     */
763	    private String normalizeAddress(String address) {
764	        if (address == null) {
765	            return "";
766	        }
767	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
768	        if (collapsed.isEmpty()) {
769	            return "";
770	        }
771	        String[] tokens = collapsed.split(" ");
772	        StringBuilder sb = new StringBuilder(collapsed.length());
773	        for (int i = 0; i < tokens.length; i++) {
774	            if (i > 0) {
775	                sb.append(' ');
776	            }
777	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
778	        }
779	        return sb.toString();
780	    }
781	}
