304	    /**
305	     * Renders the field-level errors of a {@link BindingResult} as the {@link ValidationMessageDto} list
306	     * exposed under the {@code schemaValidationErrors} property of the response.
307	     *
308	     * @param bindingResult The {@link BindingResult} carrying the rejected fields.
309	     * @return One {@link ValidationMessageDto} per field error.
310	     */
311	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
312	        return bindingResult.getFieldErrors().stream()
313	            .map(fieldError -> {
314	                String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
315	                String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
316	                String message = "Field '%s' %s (rejected value: %s)".formatted(
317	                    fieldError.getField(),
318	                    defaultMessage,
319	                    rejectedValue);
320	                return new ValidationMessageDto(message)
321	                    .putAdditionalProperty("field", fieldError.getField())
322	                    .putAdditionalProperty("rejectedValue", rejectedValue)
323	                    .putAdditionalProperty("defaultMessage", defaultMessage);
324	            })
325	            .toList();
326	    }
