233	    /**
234	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
235	     * The address is normalized in place (so a required-field check that follows rejects an
236	     * address blank after normalization), the required fields are checked, the telephone and
237	     * email are normalized in place, and the resulting telephone is rejected when it already
238	     * belongs to another owner. Each rule
239	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
240	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
241	     * to be mapped and saved.
242	     *
243	     * @param ownerFieldsDto the submitted owner fields, normalized in place
244	     */
245	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
246	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
247	        validateRequiredFields(ownerFieldsDto);
248	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
249	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
250	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
251	        rejectDuplicateEmail(ownerFieldsDto.getEmail());
252	        rejectDuplicateHousehold(ownerFieldsDto);
253	        rejectCityAtCapacity(ownerFieldsDto.getCity());
254	        rejectDailyLimitExceeded(registrationDate);
255	    }
256	
257	    /**
258	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
259	     * falls on a business day. The date supplied on the request is used when present, otherwise the
260	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
261	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
262	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
263	     * membership number's year segment, the per-day create limit) is computed against.
264	     *
265	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
266	     * @return the effective registration date rolled forward to the next business day
267	     */
268	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
269	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
270	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
271	        return toBusinessDay(effective);
272	    }
273	
274	    /**
275	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
276	     * following Monday, while a weekday is returned unchanged.
277	     *
278	     * @param date the date to adjust
279	     * @return the same date when it is a weekday, otherwise the next Monday
280	     */
281	    private LocalDate toBusinessDay(LocalDate date) {
282	        java.time.DayOfWeek day = date.getDayOfWeek();
283	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
284	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
285	        }
286	        return date;
287	    }
