289	    /**
290	     * The maximum number of owners that may be created on a single day. Once this many owners
291	     * already carry today's {@code registrationDate}, no further owner may be created today.
292	     */
293	    private static final long DAILY_OWNER_LIMIT = 100L;
294	
295	    /**
296	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
297	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
298	     * date the new owner would be stored with, so owners are capped per business day. When the limit
299	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
300	     * advice renders as a 429 Too Many Requests response.
301	     *
302	     * @param registrationDate the adjusted business-day registration date of the owner being created
303	     */
304	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
305	        long count = this.clinicService.findAllOwners().stream()
306	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
307	            .count();
308	        if (count >= DAILY_OWNER_LIMIT) {
309	            throw new DailyOwnerLimitExceededException(registrationDate);
310	        }
311	    }
312	
313	    /**
314	     * The number of owners that may carry a single day's {@code registrationDate} before that day
315	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
316	     * the create and read responses report {@code bulkSignupWarning} true for that date.
317	     */
318	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
319	
320	    /**
321	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
322	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
323	     * count is taken against the same adjusted date owners are stored with, mirroring the
324	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
325	     *
326	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
327	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
328	     */
329	    private boolean bulkSignupWarning(LocalDate registrationDate) {
330	        if (registrationDate == null) {
331	            return false;
332	        }
333	        long count = this.clinicService.findAllOwners().stream()
334	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
335	            .count();
336	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
337	    }
338	
339	    /**
340	     * The maximum number of owners a single city may hold. Once a city already contains this
341	     * many owners, no further owner may be created in it.
342	     */
343	    private static final long CITY_OWNER_CAPACITY = 50L;
344	
345	    /**
346	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
347	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
348	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
349	     * which the exception advice renders as a 409 Conflict response.
350	     *
351	     * @param city the city of the owner being created
352	     */
353	    private void rejectCityAtCapacity(String city) {
354	        long count = this.clinicService.findAllOwners().stream()
355	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
356	            .count();
357	        if (count >= CITY_OWNER_CAPACITY) {
358	            throw new CityCapacityExceededException(city);
359	        }
360	    }
361	
362	    /**
363	     * Builds the customer code assigned to a newly created owner. The code is formatted as
364	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
365	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
366	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
367	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
368	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
369	     *
370	     * @param city the owner's city
371	     * @param lastName the owner's last name
372	     * @return the formatted customer code
373	     */
374	    private String nextCustomerCode(String city, String lastName) {
375	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
376	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
377	        long sequence = this.clinicService.findAllOwners().stream()
378	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
379	            .count() + 1L;
380	        return String.format("%s-%s-%04d", city3, last3, sequence);
381	    }
382	
383	    /**
384	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
385	     * with the owner being created, compared case-insensitively. The count is taken before the
386	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
387	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
388	     *
389	     * @param firstName the first name of the owner being created
390	     * @param lastName the last name of the owner being created
391	     * @return the number of pre-existing owners sharing the same first and last name
392	     */
393	    private int countNamesakes(String firstName, String lastName) {
394	        return (int) this.clinicService.findAllOwners().stream()
395	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
396	                && lastName.equalsIgnoreCase(existing.getLastName()))
397	            .count();
398	    }
399	
400	    /**
401	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
402	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
403	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
404	     * the names of every offending field, which the exception advice renders as a 400 response
405	     * with an {@code errors} array.
406	     *
407	     * @param ownerFieldsDto the submitted owner fields
408	     */
409	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
410	        List<String> missing = new ArrayList<>();
411	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
412	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
413	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
414	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
415	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
416	        if (!missing.isEmpty()) {
417	            throw new RequiredFieldsMissingException(missing);
418	        }
419	    }
420	
421	    private void addIfBlank(List<String> missing, String fieldName, String value) {
422	        if (value == null || value.isBlank()) {
423	            missing.add(fieldName);
424	        }
425	    }
426	
427	    /**
428	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
429	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
430	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
431	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
432	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
433	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
434	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
435	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
436	     *
437	     * @param telephone the submitted telephone value
438	     * @return the normalized E.164 telephone
439	     */
440	    private String normalizeTelephone(String telephone) {
441	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
442	        String e164;
443	        if (cleaned.startsWith("+")) {
444	            e164 = "+" + cleaned.substring(1);
445	        } else {
446	            String national = cleaned;
447	            if (national.startsWith("0")) {
448	                national = national.substring(1);
449	            }
450	            e164 = "+61" + national;
451	        }
452	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
453	            throw new InvalidFieldsException(List.of("telephone"));
454	        }
455	        validateNationalNumberLength(e164);
456	        return e164;
457	    }
458	
459	    /**
460	     * The required national-number length (the digits after the country code) for each country
461	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
462	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
463	     */
464	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
465	        java.util.Map.of("61", 9, "1", 10);
466	
467	    /**
468	     * Validates the national-number length of an already syntactically valid E.164 telephone
469	     * against its country code. For each recognized country code the digits following the code
470	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
471	     * 10). When the country code is recognized but the national number is the wrong length an
472	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
473	     * response naming the {@code telephone} field. A country code that is not recognized carries
474	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
475	     *
476	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
477	     */
478	    private void validateNationalNumberLength(String e164) {
479	        String digits = e164.substring(1);
480	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
481	            .filter(entry -> digits.startsWith(entry.getKey()))
482	            // longest matching country code wins, so a shorter code cannot shadow a longer one
483	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
484	            .ifPresent(entry -> {
485	                int nationalLength = digits.length() - entry.getKey().length();
486	                if (nationalLength != entry.getValue()) {
487	                    throw new InvalidFieldsException(List.of("telephone"));
488	                }
489	            });
490	    }
491	
492	    /**
493	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
494	     * and a domain containing at least one dot, none of the parts holding whitespace or a
495	     * second {@code @}.
496	     */
497	    private static final java.util.regex.Pattern EMAIL_PATTERN =
498	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
499	
500	    /**
501	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
502	     * accepted and returned unchanged. When present it must be a syntactically valid address;
503	     * the value is stored and returned lower-cased. When present but invalid an
504	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
505	     * response naming the {@code email} field.
506	     *
507	     * @param email the submitted email value, or {@code null} when omitted
508	     * @return the lower-cased email, or {@code null} when none was supplied
509	     */
510	    private String normalizeEmail(String email) {
511	        if (email == null) {
512	            return null;
513	        }
514	        String trimmed = email.trim();
515	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
516	            throw new InvalidFieldsException(List.of("email"));
517	        }
518	        return canonicalEmail(trimmed);
519	    }
520	
521	    /**
522	     * Reduces an email to the canonical form used both to store it and to compare it against
523	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
524	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
525	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
526	     * value read back off an existing owner without risk of rejecting it. This is the single
527	     * definition of email identity: two emails denote the same address exactly when they
528	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
529	     * an email already on an existing owner can be compared for equality after both pass through
530	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
531	     *
532	     * @param email the email to canonicalize, or {@code null} when none was supplied
533	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
534	     */
535	    private String canonicalEmail(String email) {
536	        if (email == null) {
537	            return null;
538	        }
539	        return email.trim().toLowerCase(java.util.Locale.ROOT);
540	    }
541	
542	    /**
543	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
544	     * The telephone is stored in its normalized E.164 form, so a plain equality check
545	     * against every owner's telephone compares E.164 values. When a match is found a
546	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
547	     * 409 Conflict response.
548	     *
549	     * @param telephone the normalized telephone of the owner being created
550	     */
551	    private void rejectDuplicateTelephone(String telephone) {
552	        boolean taken = this.clinicService.findAllOwners().stream()
553	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
554	        if (taken) {
555	            throw new DuplicateTelephoneException(telephone);
556	        }
557	    }
558	
559	    /**
560	     * Rejects a new owner whose email is already used by any existing owner. An email is
561	     * optional, so a {@code null} email is never a duplicate. When present the email is
562	     * compared to every existing owner's email under the single canonical email identity
563	     * (trimmed and lower-cased, see {@link #canonicalEmail(String)}), so for example
564	     * {@code "Jane@Example.com"} collides with a stored {@code "jane@example.com"}. When a
565	     * match is found a {@link DuplicateEmailException} is thrown, which the exception advice
566	     * renders as a 409 Conflict response.
567	     *
568	     * @param email the normalized email of the owner being created, or {@code null} when omitted
569	     */
570	    private void rejectDuplicateEmail(String email) {
571	        String canonical = canonicalEmail(email);
572	        if (canonical == null) {
573	            return;
574	        }
575	        boolean taken = this.clinicService.findAllOwners().stream()
576	            .anyMatch(existing -> canonical.equals(canonicalEmail(existing.getEmail())));
577	        if (taken) {
578	            throw new DuplicateEmailException(canonical);
579	        }
580	    }
581	
582	    /**
583	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
584	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
585	     * for how that identity is compared). A request may bypass this rule by setting
586	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
587	     * When a household mate is found and the request did not opt in a
588	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
589	     * Conflict response.
590	     *
591	     * @param ownerFieldsDto the submitted owner fields
592	     */
593	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
594	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
595	            return;
596	        }
597	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
598	        if (taken) {
599	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
600	        }
601	    }
602	
603	    /**
604	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
605	     * set to {@code true}. The identifier is the one the owner would receive
606	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
607	     * household identity so every owner in the same household resolves to the same stable value.
608	     * The new owner receives that value, and any existing household mates that do not yet carry it
609	     * are updated so the whole household shares one identifier. When the request did not opt in the
610	     * owner is left without a household identifier.
611	     *
612	     * @param owner the newly created owner, mutated in place with its household identifier
613	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
614	     */
615	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
616	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
617	        if (householdId == null) {
618	            return;
619	        }
620	        owner.setHouseholdId(householdId);
621	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
622	            if (!householdId.equals(mate.getHouseholdId())) {
623	                mate.setHouseholdId(householdId);
624	                this.clinicService.saveOwner(mate);
625	            }
626	        }
627	    }
628	
629	    /**
630	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
631	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
632	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
633	     * from the owner's household identity (its {@code lastName} and {@code address}, see
634	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
635	     * later store and every household mate resolves to the same identifier. When the request did not
636	     * opt in the owner belongs to no shared household and {@code null} is returned.
637	     *
638	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
639	     * @return the household identifier the owner would receive, or {@code null} when it shares none
640	     */
641	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
642	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
643	            return null;
644	        }
645	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
646	    }
647	
648	    /**
649	     * Derives the stable {@code householdId} shared by every owner in the household identified by
650	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
651	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
652	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
653	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
654	     *
655	     * @param lastName the household's last name
656	     * @param address the household's address
657	     * @return the deterministic household identifier
658	     */
659	    private String householdIdFor(String lastName, String address) {
660	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
661	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
662	        try {
663	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
664	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
665	            StringBuilder sb = new StringBuilder();
666	            for (int i = 0; i < 8; i++) {
667	                sb.append(String.format("%02X", digest[i]));
668	            }
669	            return "HH-" + sb;
670	        }
671	        catch (java.security.NoSuchAlgorithmException e) {
672	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
673	        }
674	    }
675	
676	    /**
677	     * Counts the owners that belong to the household identified by the given {@code householdId},
678	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
679	     * of owners, so after a create it reflects the household's size including the newly persisted
680	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
681	     * household and yields {@code 0}.
682	     *
683	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
684	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
685	     */
686	    private int countHouseholdMembers(String householdId) {
687	        if (householdId == null) {
688	            return 0;
689	        }
690	        return (int) this.clinicService.findAllOwners().stream()
691	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
692	            .count();
693	    }
694	
695	    /**
696	     * Finds an existing owner that shares a household with the given {@code lastName} and
697	     * {@code address}. When several owners match, the first one encountered is returned.
698	     *
699	     * @param lastName the last name to match on
700	     * @param address the address to match on
701	     * @return the first owner sharing the household, or empty when none exists
702	     */
703	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
704	        return findHouseholdMates(lastName, address).stream().findFirst();
705	    }
706	
707	    /**
708	     * Finds every existing owner that shares a household with the given {@code lastName} and
709	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
710	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
711	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
712	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
713	     * every rule that reasons about households.
714	     *
715	     * @param lastName the last name to match on
716	     * @param address the address to match on
717	     * @return the owners sharing the household, in encounter order (possibly empty)
718	     */
719	    private List<Owner> findHouseholdMates(String lastName, String address) {
720	        String normalizedLastName = collapseWhitespace(lastName);
721	        String normalizedAddress = normalizeAddress(address);
722	        return this.clinicService.findAllOwners().stream()
723	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
724	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
725	            .toList();
726	    }
727	
728	    /**
729	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
730	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
731	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
732	     *
733	     * @param value the value to collapse, or {@code null}
734	     * @return the whitespace-collapsed value, never {@code null}
735	     */
736	    private String collapseWhitespace(String value) {
737	        if (value == null) {
738	            return "";
739	        }
740	        return value.trim().replaceAll("\\s+", " ");
741	    }
742	
743	    /**
744	     * Common street-type abbreviations expanded during address normalization, keyed by their
745	     * upper-cased token.
746	     */
747	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
748	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
749	
750	    /**
751	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
752	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
753	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
754	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
755	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
756	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
757	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
758	     * everywhere an address is stored or compared.
759	     *
760	     * @param address the submitted address value, or {@code null}
761	     * @return the normalized address, never {@code null}
762	     */
763	    private String normalizeAddress(String address) {
764	        if (address == null) {
765	            return "";
766	        }
767	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
768	        if (collapsed.isEmpty()) {
769	            return "";
770	        }
771	        String[] tokens = collapsed.split(" ");
772	        StringBuilder sb = new StringBuilder(collapsed.length());
773	        for (int i = 0; i < tokens.length; i++) {
774	            if (i > 0) {
775	                sb.append(' ');
776	            }
777	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
778	        }
779	        return sb.toString();
780	    }
781	}
